# Generated by manage.py generate_test_cases.
import json

from django.contrib.contenttypes.models import ContentType

from bloomerp.models.forms.form import Form
from bloomerp.services.sectioned_layout_services import create_default_layout
from bloomerp.tests.base import (
    BloomerpAPIDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)


class TestFormSubmitView(BloomerpAPIDetailViewTestCase):
    """Tests function `form_submit_view` from `bloomerp/views/api/forms/submit.py`."""

    view_name = 'api_form_submit'
    model = Form

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="Public form exposes its submission endpoint",
                description=(
                    "UC: A form enables public embedding.\n"
                    "Expected Result: Its custom submission URL is reachable."
                ),
                prepare=lambda scenario: self.prepare_form(
                    scenario, public_embed_enabled=True
                ),
                expected=ExpectedResult(
                    response_validators=self.public_endpoint_matches_form,
                ),
            ),
            RequestScenario(
                name="Private form hides its submission endpoint",
                description=(
                    "UC: A form does not enable public embedding.\n"
                    "Expected Result: Its public submission endpoint returns 404."
                ),
                prepare=lambda scenario: self.prepare_form(
                    scenario, public_embed_enabled=False
                ),
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Anonymous user cannot open authentication-required form",
                description=(
                    "UC: A public form requires authentication.\n"
                    "Expected Result: An anonymous request is forbidden."
                ),
                prepare=lambda scenario: self.prepare_form(
                    scenario,
                    public_embed_enabled=True,
                    requires_authentication=True,
                ),
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Public form accepts browser submission",
                description=(
                    "UC: A visitor submits valid form-encoded values.\n"
                    "Expected Result: The submission is stored with every supplied value."
                ),
                method="POST",
                data={"first_name": "John", "last_name": "Doe", "age": 42},
                prepare=lambda scenario: self.prepare_form(
                    scenario, public_embed_enabled=True
                ),
                expected=ExpectedResult(
                    response_validators=lambda response: self.submission_matches(
                        response,
                        {"first_name": "John", "last_name": "Doe", "age": 42},
                    )
                ),
            ),
            RequestScenario(
                name="Public form supports CORS preflight",
                description=(
                    "UC: An embedded client performs a CORS preflight.\n"
                    "Expected Result: The endpoint advertises POST and content-type support."
                ),
                method="OPTIONS",
                headers={
                    "origin": "https://example.com",
                    "access-control-request-method": "POST",
                    "access-control-request-headers": "content-type",
                },
                prepare=lambda scenario: self.prepare_form(
                    scenario, public_embed_enabled=True
                ),
                expected=ExpectedResult(
                    status_code=204,
                    response_validators=self.cors_preflight_is_valid,
                ),
            ),
            RequestScenario(
                name="Public form accepts JSON submission",
                description=(
                    "UC: An embedded client submits JSON.\n"
                    "Expected Result: Typed values are stored and CORS is allowed."
                ),
                method="POST",
                data=json.dumps(
                    {"first_name": "David", "last_name": "Bloomer", "age": 42}
                ),
                content_type="application/json",
                headers={"origin": "https://example.com"},
                prepare=lambda scenario: self.prepare_form(
                    scenario, public_embed_enabled=True
                ),
                expected=ExpectedResult(
                    response_validators=lambda response: (
                        response.headers.get("Access-Control-Allow-Origin") == "*"
                        and self.submission_matches(
                            response,
                            {"first_name": "David", "last_name": "Bloomer", "age": 42},
                        )
                    )
                ),
            ),
        ]

    def prepare_form(self, scenario, **overrides):
        values = {
            "name": "Scenario form",
            "description": "A form used by declarative API scenarios",
            "requires_review": False,
            "requires_authentication": False,
            "public_embed_enabled": False,
            "content_type": ContentType.objects.get_for_model(self.CustomerModel),
        }
        values.update(overrides)
        values["layout"] = create_default_layout(self.CustomerModel).model_dump()
        self.form = Form.objects.create(**values)
        scenario.view_kwargs = {"pk": self.form.pk}

    def public_endpoint_matches_form(self, _response):
        return self.form.submit_api_url == f"/api/forms/{self.form.pk}/submit/"

    def submission_matches(self, _response, expected):
        submission = self.form.submissions.first()
        return submission is not None and all(
            submission.data.get(key) == value for key, value in expected.items()
        )

    @staticmethod
    def cors_preflight_is_valid(response):
        return (
            response.headers.get("Access-Control-Allow-Origin") == "*"
            and "POST" in response.headers.get("Access-Control-Allow-Methods", "")
            and response.headers.get("Access-Control-Allow-Headers") == "content-type"
        )
